  void Library(){activeMetricCards=null;activeProgress=null;clock=null;page.Children.Clear();if(repo==null){Reset("Biblioteca educativa","Catálogo indisponível.");return;}Border hero=new Border{Background=new LinearGradientBrush(Color.FromRgb(166,0,0),Color.FromRgb(217,0,0),45),CornerRadius=new CornerRadius(15),Padding=new Thickness(24),Margin=new Thickness(0,0,0,14)};Grid hg=new Grid();hg.ColumnDefinitions.Add(new ColumnDefinition());hg.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});StackPanel ht=new StackPanel{VerticalAlignment=VerticalAlignment.Center};ht.Children.Add(T("Biblioteca educativa",28,true,Brushes.White));ht.Children.Add(T("Descubra novos assuntos enquanto pratica digitação.",14,false,Brushes.White));ht.Children.Add(T(repo.Categories.Count+" categorias • "+repo.Activities.Count+" atividades",13,true,Brushes.White));hg.Children.Add(ht);Image teach=Pic("Assets/mascote-ensinando.png",130);Grid.SetColumn(teach,1);hg.Children.Add(teach);hero.Child=hg;page.Children.Add(hero);
   categoryCards=new WrapPanel{Margin=new Thickness(-5,0,-5,8)};foreach(Category category in repo.Categories){Border card=new Border{Width=205,MinHeight=215,Background=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(226,229,234)),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(13),Margin=new Thickness(5),Padding=new Thickness(11),Cursor=System.Windows.Input.Cursors.Hand};StackPanel body=new StackPanel();Image art=Pic("Assets/Categorias/"+category.Id+".png",92);art.HorizontalAlignment=HorizontalAlignment.Center;body.Children.Add(art);body.Children.Add(T(category.Name,16,true));body.Children.Add(T(category.Description,12,false,new SolidColorBrush(Color.FromRgb(84,92,105))));body.Children.Add(T(repo.Activities.Count(x=>x.CategoryId==category.Id)+" atividades",12,true,Red));card.Child=body;card.MouseLeftButtonUp+=delegate{selectedCategoryId=category.Id;Render();};categoryCards.Children.Add(card);}page.Children.Add(categoryCards);
