  void Render(){if(repo==null||query==null)return;string d=diff.SelectedIndex>0?(string)diff.SelectedItem:null;var acts=repo.Find(query.Text,d,selectedCategoryId);resultCount.Text=acts.Count+" atividades encontradas"+(selectedCategoryId==null?"":" • "+repo.Categories.First(c=>c.Id==selectedCategoryId).Name);for(int i=page.Children.Count-1;i>=4;i--)page.Children.RemoveAt(i);foreach(Activity a in acts){Border card=new Border{Background=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(226,229,234)),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(13),Padding=new Thickness(16),Margin=new Thickness(5)};StackPanel row=new StackPanel();row.Children.Add(T(a.Difficulty.ToUpper(),11,true,Red));row.Children.Add(T(a.Title,18,true));row.Children.Add(T(a.Description,14,false));row.Children.Add(T(a.EstimatedMinutes+" min • "+a.WordCount+" palavras",12,false,new SolidColorBrush(Color.FromRgb(84,92,105))));row.Children.Add(B("Praticar",delegate{OpenActivity(a);}));card.Child=row;page.Children.Add(card);}if(acts.Count==0)page.Children.Add(T("Nenhuma atividade encontrada. Limpe os filtros ou tente outra busca.",16,true));}
  void OpenActivity(Activity activity){if(session==null||session.Finished){session=new SessionManager(durationMinutes,new SessionClock());resultsVisible=false;}if(session.Open(activity))Practice();else Results();}
