   Grid headingGrid=new Grid();headingGrid.ColumnDefinitions.Add(new ColumnDefinition());headingGrid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});StackPanel headingText=new StackPanel();headingText.Children.Add(T(activity.Title,25,true,Brushes.White));headingText.Children.Add(T(activity.Difficulty+" • "+activity.EstimatedMinutes+" min",13,false,Brushes.White));headingGrid.Children.Add(headingText);clock=T(FormatRemaining(session.Remaining),28,true,Brushes.White);Grid.SetColumn(clock,1);headingGrid.Children.Add(clock);heading.Child=headingGrid;page.Children.Add(heading);
