  void UpdatePracticeMetrics(Panel cards,ProgressBar bar){if(session==null||session.Engine==null||cards.Children.Count<4)return;string[] values={(session.WordsPerMinute.HasValue?session.WordsPerMinute.Value.ToString("0.#"):"—"),(session.Accuracy.HasValue?session.Accuracy.Value.ToString("0.#")+"%":"—"),session.TotalErrors.ToString(),session.CurrentErrors.ToString()};for(int i=0;i<4;i++){StackPanel content=(StackPanel)((Border)cards.Children[i]).Child;((TextBlock)content.Children[1]).Text=values[i];}stats.Text="Progresso "+session.Engine.Progress.ToString("0")+"% • caractere "+session.Engine.Entered+" de "+session.Engine.Reference.Count;bar.Value=session.Engine.Progress;}
  static string FormatRemaining(TimeSpan value){if(value<TimeSpan.Zero)value=TimeSpan.Zero;return string.Format("{0:00}:{1:00}",(int)Math.Floor(value.TotalMinutes),value.Seconds);}
  void Question(QuizQuestion quiz){Reset("Texto concluído!","Quer experimentar uma pergunta sobre o texto? O tempo da sessão continua contando.");Border banner=new Border{Background=new LinearGradientBrush(Color.FromRgb(166,0,0),Color.FromRgb(217,0,0),45),CornerRadius=new CornerRadius(15),Padding=new Thickness(24)};StackPanel bannerText=new StackPanel();bannerText.Children.Add(T("Texto concluído!",28,true,Brushes.White));bannerText.Children.Add(T("Responda à pergunta educativa para continuar sua sessão.",14,false,Brushes.White));banner.Child=bannerText;page.Children.Add(banner);Border card=LegacyControls.Card(new StackPanel());StackPanel content=(StackPanel)card.Child;content.Children.Add(T(quiz.Prompt,20,true));TextBlock feedback=T("",14,true,Red);Button[] answers=new Button[quiz.Options.Length];bool answered=false;for(int i=0;i<quiz.Options.Length;i++){int index=i;answers[i]=B(quiz.Options[i],delegate{if(answered)return;answered=true;bool correct=index==quiz.AnswerIndex;feedback.Text=(correct?"Isso mesmo! ":"Vamos conferir. ")+quiz.Explanation;foreach(Button choice in answers)choice.IsEnabled=false;},false);answers[i].HorizontalContentAlignment=HorizontalAlignment.Left;answers[i].MinWidth=250;content.Children.Add(answers[i]);}content.Children.Add(feedback);Button next=B("Continuar",delegate{if(answered)Library();else MessageBox.Show("Escolha uma alternativa antes de continuar.","IT Digitação");},true);content.Children.Add(next);page.Children.Add(card);clock=null;}
  void Results(){Reset("Resumo da prática","Continue praticando para conquistar novas metas.");page.Children.Add(Pic("Assets/mascote-celebrando.png",150));if(session!=null){page.Children.Add(T("Atividades concluídas: "+session.CompletedCount,18,true));page.Children.Add(T("Precisão "+(session.Accuracy.HasValue?session.Accuracy.Value.ToString("0.#")+"%":"—")+" • Erros "+session.TotalErrors+" • Corrigidos "+session.CorrectedErrors+" • Velocidade "+(session.WordsPerMinute.HasValue?session.WordsPerMinute.Value.ToString("0.#")+" ppm":"—"),15,false));page.Children.Add(T("Estrelas: "+SessionAwards.Stars(session.Evaluated,session.Accuracy),18,true));}clock=null;page.Children.Add(B("Voltar à biblioteca",Library));page.Children.Add(B("Início",Home,false));resultsVisible=true;}
  void Guide(){Reset("Guia ABNT2","Posição inicial: ASDF JKLÇ. Polegares na barra de espaço.");page.Children.Add(Pic("Assets/mascote-ensinando.png",170));page.Children.Add(T("Mão esquerda: mindinho A, anelar S, médio D, indicador F. Mão direita: indicador J, médio K, anelar L, mindinho Ç.",17,false));page.Children.Add(B("Exercitar posição inicial",delegate{OpenActivity(Activity.HomeRowExercise());}));}
  void Settings(){Reset("Configurações","Personalize a experiência de digitação. Suas preferências são salvas neste perfil.");Border appearance=SettingsCard("Aparência");StackPanel appearanceContent=(StackPanel)appearance.Child;appearanceContent.Children.Add(T("Tamanho da fonte",15,true));Slider font=new Slider{Minimum=12,Maximum=28,Value=preferences.FontPoints,Width=360,TickFrequency=1,IsSnapToTickEnabled=true,HorizontalAlignment=HorizontalAlignment.Left};TextBlock preview=T("Prévia do texto",16,false);font.ValueChanged+=delegate{preview.FontSize=font.Value;};appearanceContent.Children.Add(font);appearanceContent.Children.Add(preview);page.Children.Add(appearance);
